function reminderPath(id=""){return `users/${activeUser.uid}/reminders${id?`/${id}`:""}`}
function listenReminders(){onValue(ref(database,reminderPath()),snapshot=>{const data=snapshot.val()||{};reminders=Object.entries(data).map(([id,value])=>({id,...value})).sort((a,b)=>`${a.date||"9999-12-31"} ${a.time||"23:59"}`.localeCompare(`${b.date||"9999-12-31"} ${b.time||"23:59"}`));cleanupReminders();renderReminders()})}
function cleanupReminders(){const limit=Date.now()-RETENTION_MS,toTrash=reminders.filter(item=>item.completed&&!item.deleted&&typeof item.completedAt==="number"&&item.completedAt<=limit),toDelete=reminders.filter(item=>item.deleted&&typeof item.deletedAt==="number"&&item.deletedAt<=limit),legacyTrash=reminders.filter(item=>item.deleted&&typeof item.deletedAt!=="number");const jobs=[...toTrash.map(item=>update(ref(database,reminderPath(item.id)),{deleted:true,deletedAt:serverTimestamp()})),...toDelete.map(item=>remove(ref(database,reminderPath(item.id)))),...legacyTrash.map(item=>update(ref(database,reminderPath(item.id)),{deletedAt:serverTimestamp()}))];if(jobs.length)Promise.all(jobs).catch(error=>console.error("No se pudo completar la limpieza automática de recordatorios.",error))}
function escapeHTML(value=""){const node=document.createElement("div");node.textContent=value;return node.innerHTML}
function parseReminderItems(value){return value.split("\n").filter(line=>line.trim()).slice(0,30).map(line=>{const spaces=line.match(/^[\t ]*/)[0],level=spaces.includes("\t")||spaces.length>=2?1:0,text=line.trim().replace(/^[-•]\s*/,"");return{text,level,done:false}}).filter(item=>item.text)}
function serializeReminderItems(items=[]){return(Array.isArray(items)?items:[]).map(item=>`${item.level?"  ":""}${item.text}`).join("\n")}
function formatReminderDate(date,time){if(!date)return time?`Sin fecha · ${time}`:"Sin fecha ni hora";const parsed=new Date(`${date}T${time||"12:00"}`),today=new Date();today.setHours(0,0,0,0);const tomorrow=new Date(today);tomorrow.setDate(today.getDate()+1);let label=parsed.toLocaleDateString("es-AR",{day:"numeric",month:"short"});if(parsed.toDateString()===today.toDateString())label="Hoy";else if(parsed.toDateString()===tomorrow.toDateString())label="Mañana";return `${label}${time?` · ${time}`:""}`}
function isOverdue(item){if(item.completed||!item.date)return false;const end=item.time||"23:59";return new Date(`${item.date}T${end}`)<new Date()}
function renderReminders(){const active=reminders.filter(item=>!item.deleted),trash=reminders.filter(item=>item.deleted),pending=active.filter(item=>!item.completed).length,completed=active.length-pending;$("pendingCount").textContent=pending;$("completedCount").textContent=completed;$("trashCount").textContent=trash.length;if($("welcomePendingCount"))$("welcomePendingCount").textContent=pending;const visible=reminderFilter==="trash"?trash:active.filter(item=>reminderFilter==="all"||(reminderFilter==="completed"?item.completed:!item.completed));$("clearReminders").classList.toggle("hidden",reminderFilter!=="completed"&&reminderFilter!=="trash");$("clearReminders").textContent=reminderFilter==="trash"?"Vaciar papelera":"Borrar completados";$("remindersList").innerHTML=visible.map(item=>{const items=Array.isArray(item.items)?item.items:[],subitems=items.length?`<div class="reminder-subitems">${items.map((sub,index)=>item.deleted?`<div class="subitem level-${sub.level||0} ${sub.done?"done":""}"><span class="sub-check"><i class="fa-solid fa-check"></i></span><span>${escapeHTML(sub.text)}</span></div>`:`<button class="subitem level-${sub.level||0} ${sub.done?"done":""}" data-action="subtoggle" data-id="${item.id}" data-index="${index}"><span class="sub-check"><i class="fa-solid fa-check"></i></span><span>${escapeHTML(sub.text)}</span></button>`).join("")}</div>`:"";return`<article class="reminder-card ${item.completed?"completed":""} ${item.deleted?"deleted":""} ${isOverdue(item)?"overdue":""}">${item.deleted?'<span class="deleted-marker"><i class="fa-regular fa-trash-can"></i></span>':`<button class="complete-reminder" data-action="toggle" data-id="${item.id}" aria-label="${item.completed?"Marcar pendiente":"Marcar completado"}"><i class="fa-solid fa-check"></i></button>`}<div class="reminder-info"><h3>${escapeHTML(item.title)}</h3>${item.description?`<p>${escapeHTML(item.description)}</p>`:""}${subitems}<span class="reminder-date"><i class="fa-regular fa-clock"></i>${isOverdue(item)?"Vencido · ":""}${formatReminderDate(item.date,item.time)}</span></div><div class="reminder-actions">${item.deleted?"":`<button class="edit-reminder" data-action="edit" data-id="${item.id}" aria-label="Editar"><i class="fa-regular fa-pen-to-square"></i></button>`}<button class="delete-reminder ${item.deleted?"restore-reminder":""}" data-action="${item.deleted?"restore":"delete"}" data-id="${item.id}" aria-label="${item.deleted?"Recuperar":"Eliminar"}"><i class="fa-solid ${item.deleted?"fa-rotate-left":"fa-trash-can"}"></i></button></div></article>`}).join("");$("reminderEmpty").classList.toggle("hidden",visible.length>0)}
function toggleForm(show,item=null){const form=$("reminderForm");if(show){editingReminderId=item?.id||null;$("reminderFormTitle").textContent=item?"Editar recordatorio":"Nuevo recordatorio";$("saveReminder").textContent=item?"Guardar cambios":"Guardar recordatorio";$("reminderTitle").value=item?.title||"";$("reminderDate").value=item?.date||"";$("reminderTime").value=item?.time||"";$("reminderDescription").value=item?.description||"";$("reminderItems").value=serializeReminderItems(item?.items);form.classList.add("open");setTimeout(()=>$("reminderTitle").focus(),180)}else{form.classList.remove("open");window.setTimeout(()=>{form.reset();editingReminderId=null;$("reminderError").classList.add("hidden")},330)}}
$("newReminderButton").addEventListener("click",()=>toggleForm(true));$("closeReminderForm").addEventListener("click",()=>toggleForm(false));$("cancelReminder").addEventListener("click",()=>toggleForm(false));
$("reminderForm").addEventListener("submit",async event=>{event.preventDefault();const title=$("reminderTitle").value.trim(),date=$("reminderDate").value,time=$("reminderTime").value,description=$("reminderDescription").value.trim(),parsedItems=parseReminderItems($("reminderItems").value),previous=reminders.find(item=>item.id===editingReminderId),oldItems=Array.isArray(previous?.items)?previous.items:[],items=parsedItems.map((item,index)=>({...item,done:oldItems[index]?.text===item.text&&Number(oldItems[index]?.level||0)===item.level?Boolean(oldItems[index].done):false}));if(!title){$("reminderError").textContent="Escribe un título para el recordatorio.";$("reminderError").classList.remove("hidden");return}$("saveReminder").disabled=true;try{if(editingReminderId)await update(ref(database,reminderPath(editingReminderId)),{title,date,time,description,items,updatedAt:serverTimestamp()});else{const itemRef=push(ref(database,reminderPath()));await set(itemRef,{title,date,time,description,items,completed:false,deleted:false,createdAt:serverTimestamp()})}toggleForm(false)}catch(error){console.error(error);$("reminderError").textContent="No se pudo guardar el recordatorio.";$("reminderError").classList.remove("hidden")}finally{$("saveReminder").disabled=false}});
$("reminderFilters").addEventListener("click",event=>{const button=event.target.closest("button[data-filter]");if(!button)return;document.querySelector(".reminder-filters .active")?.classList.remove("active");button.classList.add("active");reminderFilter=button.dataset.filter;renderReminders()});
$("remindersList").addEventListener("click",async event=>{const button=event.target.closest("button[data-action]");if(!button)return;const item=reminders.find(reminder=>reminder.id===button.dataset.id);if(!item)return;if(button.dataset.action==="edit")toggleForm(true,item);else if(button.dataset.action==="toggle")await update(ref(database,reminderPath(item.id)),{completed:!item.completed,completedAt:!item.completed?serverTimestamp():null});else if(button.dataset.action==="delete")await update(ref(database,reminderPath(item.id)),{deleted:true,deletedAt:serverTimestamp()});else if(button.dataset.action==="restore")await update(ref(database,reminderPath(item.id)),{deleted:false,deletedAt:null,completed:false,completedAt:null});else if(button.dataset.action==="subtoggle"){const index=Number(button.dataset.index),items=Array.isArray(item.items)?item.items:[];if(items[index])await update(ref(database,`${reminderPath(item.id)}/items/${index}`),{done:!items[index].done})}})
$("clearReminders").addEventListener("click",async()=>{const targets=reminders.filter(item=>reminderFilter==="trash"?item.deleted:item.completed&&!item.deleted);if(!targets.length)return;const message=reminderFilter==="trash"?"¿Vaciar la papelera definitivamente?":"¿Borrar definitivamente todos los completados?";if(!window.confirm(message))return;$("clearReminders").disabled=true;try{await Promise.all(targets.map(item=>remove(ref(database,reminderPath(item.id)))))}finally{$("clearReminders").disabled=false}})


