const MAX_FILE_SIZE=25*1024*1024;
function drivePath(id=""){return `users/${activeUser.uid}/driveItems${id?`/${id}`:""}`}
function normalizeParentId(value){return value&&value!=="root"?value:null}
function listenDriveItems(){onValue(ref(database,drivePath()),snapshot=>{const data=snapshot.val()||{};driveItems=Object.entries(data).map(([id,value])=>({id,...value}));if(currentFolderId&&!driveItems.some(item=>item.id===currentFolderId&&item.type==="folder"))currentFolderId=null;renderDriveItems()})}
function getDriveItem(id){return driveItems.find(item=>item.id===id)}
function childItems(parentId=currentFolderId){const normalized=normalizeParentId(parentId);return driveItems.filter(item=>normalizeParentId(item.parentId)===normalized)}
function folderPathIds(folderId){const ids=[];let current=folderId,guard=0;while(current&&guard++<100){const item=getDriveItem(current);if(!item||item.type!=="folder")break;ids.unshift(item.id);current=normalizeParentId(item.parentId)}return ids}
function folderPathLabel(folderId){const names=folderPathIds(folderId).map(id=>getDriveItem(id)?.name).filter(Boolean);return names.length?`Inicio / ${names.join(" / ")}`:"Inicio"}
function fileExtension(name=""){const match=name.toLowerCase().match(/\.([a-z0-9]+)$/);return match?match[1]:""}
function fileKind(name=""){const ext=fileExtension(name);if(ext==="pdf")return"pdf";if(ext==="docx")return"word";return""}
function fileBaseName(name=""){const ext=fileExtension(name);return ext?name.slice(0,-ext.length-1):name}
function safeFileName(name=""){return name.replace(/[\\/:*?"<>|#%{}]/g,"-").replace(/\s+/g," ").trim().slice(0,120)||"documento"}
function formatFileSize(bytes=0){if(bytes<1024)return`${bytes} B`;if(bytes<1024*1024)return`${(bytes/1024).toFixed(bytes<10*1024?1:0)} KB`;return`${(bytes/(1024*1024)).toFixed(bytes<10*1024*1024?1:0)} MB`}
function formatDriveDate(value){if(!value||typeof value!=="number")return"Ahora";return new Date(value).toLocaleDateString("es-AR",{day:"2-digit",month:"short",year:"numeric"})}
function escapeAttr(value=""){return escapeHTML(value).replace(/"/g,"&quot;")}
function renderBreadcrumbs(){const root=`<button type="button" data-folder-id="root"><i class="fa-solid fa-house"></i><span>Archivos</span></button>`;const crumbs=folderPathIds(currentFolderId).map((id,index,array)=>{const folder=getDriveItem(id);return`<i class="fa-solid fa-chevron-right"></i><button type="button" data-folder-id="${id}" ${index===array.length-1?'class="current"':''}>${escapeHTML(folder?.name||"Carpeta")}</button>`}).join("");$("filesBreadcrumbs").innerHTML=root+crumbs}
function renderDriveItems(){if(!$("filesGrid"))return;renderBreadcrumbs();const query=$("filesSearch")?.value.trim().toLowerCase()||"";const visible=childItems().filter(item=>!query||String(item.name||"").toLowerCase().includes(query)).sort((a,b)=>a.type===b.type?String(a.name||"").localeCompare(String(b.name||""),"es",{sensitivity:"base"}):a.type==="folder"?-1:1);$("filesGrid").classList.toggle("list-mode",filesViewMode==="list");$("filesGrid").innerHTML=visible.map(item=>item.type==="folder"?renderFolderCard(item):renderFileCard(item)).join("");$("filesEmpty").classList.toggle("hidden",visible.length>0||Boolean(query));if(query&&visible.length===0){$("filesEmpty").classList.remove("hidden");$("filesEmpty").querySelector("h2").textContent="Sin resultados";$("filesEmpty").querySelector("p").textContent="No encontramos elementos con ese nombre en esta carpeta.";$("filesEmpty").querySelector("div").classList.add("hidden")}else{$("filesEmpty").querySelector("h2").textContent="Esta carpeta está vacía";$("filesEmpty").querySelector("p").textContent="Creá una carpeta o subí un documento para empezar.";$("filesEmpty").querySelector("div").classList.remove("hidden")}}
function renderFolderCard(item){const count=childItems(item.id).length;return`<article class="drive-card folder-card" data-id="${item.id}" data-type="folder"><button class="drive-card-main" type="button" data-drive-action="open-folder" data-id="${item.id}"><span class="drive-icon folder"><i class="fa-solid fa-folder"></i></span><span class="drive-info"><strong>${escapeHTML(item.name)}</strong><small>${count} ${count===1?"elemento":"elementos"} · ${formatDriveDate(item.updatedAt||item.createdAt)}</small></span></button><div class="drive-actions"><button type="button" data-drive-action="edit" data-id="${item.id}" aria-label="Editar carpeta"><i class="fa-regular fa-pen-to-square"></i></button><button class="danger" type="button" data-drive-action="delete" data-id="${item.id}" aria-label="Eliminar carpeta"><i class="fa-regular fa-trash-can"></i></button></div></article>`}
function renderFileCard(item){const isPdf=item.fileType==="pdf",ext=(item.extension||fileExtension(item.name)).toUpperCase(),canEditContent=isPdf||item.extension==="docx";return`<article class="drive-card file-card" data-id="${item.id}" data-type="file"><button class="drive-card-main" type="button" data-drive-action="open-file" data-id="${item.id}"><span class="drive-icon ${isPdf?"pdf":"word"}"><i class="fa-solid ${isPdf?"fa-file-pdf":"fa-file-word"}"></i></span><span class="drive-info"><strong>${escapeHTML(item.name)}</strong><small>${ext} · ${formatFileSize(Number(item.size)||0)} · ${formatDriveDate(item.updatedAt||item.createdAt)}</small></span></button><div class="drive-actions">${canEditContent?`<button type="button" data-drive-action="edit-content" data-id="${item.id}" aria-label="Editar contenido"><i class="fa-solid fa-pen"></i></button>`:""}<button type="button" data-drive-action="edit" data-id="${item.id}" aria-label="Cambiar nombre o ubicación"><i class="fa-solid fa-sliders"></i></button><button type="button" data-drive-action="download" data-id="${item.id}" aria-label="Descargar archivo"><i class="fa-solid fa-arrow-down"></i></button><button class="danger" type="button" data-drive-action="delete" data-id="${item.id}" aria-label="Eliminar archivo"><i class="fa-regular fa-trash-can"></i></button></div></article>`}
function openFilesModal(id){$(id).classList.remove("hidden");document.body.classList.add("modal-open")}
function closeFilesModal(id){$(id).classList.add("hidden");if(document.querySelectorAll(".files-modal:not(.hidden)").length===0)document.body.classList.remove("modal-open")}
function openNewFolderModal(){$("folderForm").reset();$("folderError").classList.add("hidden");openFilesModal("folderModal");setTimeout(()=>$('folderName').focus(),80)}
function descendantFolderIds(folderId){const result=new Set(),walk=id=>{driveItems.filter(item=>item.type==="folder"&&normalizeParentId(item.parentId)===id).forEach(folder=>{if(!result.has(folder.id)){result.add(folder.id);walk(folder.id)}})};walk(folderId);return result}
function buildFolderOptions(item){const blocked=item?.type==="folder"?descendantFolderIds(item.id):new Set();if(item?.type==="folder")blocked.add(item.id);const folders=driveItems.filter(folder=>folder.type==="folder"&&!blocked.has(folder.id)).sort((a,b)=>folderPathLabel(a.id).localeCompare(folderPathLabel(b.id),"es"));return[`<option value="root">Archivos</option>`,...folders.map(folder=>`<option value="${folder.id}">${escapeHTML(folderPathLabel(folder.id))}</option>`)].join("")}
function openEditDriveItem(item){editingDriveItemId=item.id;$("editItemModalTitle").textContent=item.type==="folder"?"Editar carpeta":"Editar archivo";$("editItemName").value=item.type==="file"?fileBaseName(item.name):item.name;$("editItemParent").innerHTML=buildFolderOptions(item);$("editItemParent").value=normalizeParentId(item.parentId)||"root";$("editItemHelp").textContent=item.type==="file"?`Podés cambiar el nombre o mover el ${item.fileType==="pdf"?"PDF":"documento de Word"} a otra carpeta.`:"Podés renombrar o mover esta carpeta.";$("editItemError").classList.add("hidden");openFilesModal("editItemModal");setTimeout(()=>$('editItemName').focus(),80)}
async function createFolder(name){const itemRef=push(ref(database,drivePath()));await set(itemRef,{type:"folder",name,parentId:currentFolderId||null,createdAt:serverTimestamp(),updatedAt:serverTimestamp()})}
function canonicalFileType(kind){return kind==="pdf"?"application/pdf":"application/vnd.openxmlformats-officedocument.wordprocessingml.document"}
function supabaseReady(){return supabaseConfigured&&Boolean(supabase)}
async function storageApi(action,payload={}){if(!activeUser)throw new Error("Sesión no disponible");const token=await activeUser.getIdToken();const response=await fetch("/api/files",{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${token}`},body:JSON.stringify({action,...payload})}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||"No se pudo acceder al almacenamiento");return data}
async function uploadDocument(file,path,contentType,upsert=false){const signed=await storageApi("create-upload",{path,contentType,size:file.size,upsert}),result=await supabase.storage.from(supabaseConfig.bucket).uploadToSignedUrl(signed.path,signed.token,file,{contentType,cacheControl:"3600"});if(result.error)throw result.error;return result.data}
function limitWait(promise,timeout=30000){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{const error=new Error("La operación tardó demasiado.");error.code="storage/operation-stalled";reject(error)},timeout);promise.then(value=>{clearTimeout(timer);resolve(value)},error=>{clearTimeout(timer);reject(error)})})}
function uploadErrorMessage(error){if(!supabaseReady())return"Falta completar supabase-config.js.";if(/configur|variable|bucket/i.test(error?.message||""))return error.message;return"No se pudo subir el documento. Revisá la configuración de Supabase e intentá nuevamente."}
async function uploadFiles(fileList){const files=Array.from(fileList||[]);if(!files.length)return;if(!supabaseReady()){showUploadToast("Supabase","Completá supabase-config.js antes de subir archivos.",false,true);return}$("uploadFileButton").disabled=true;try{for(const file of files){const kind=fileKind(file.name);if(!kind){window.alert(`“${file.name}” no se subió. Solo se permiten archivos Word y PDF.`);continue}if(file.size>MAX_FILE_SIZE){window.alert(`“${file.name}” supera el límite de 25 MB.`);continue}const itemRef=push(ref(database,drivePath())),id=itemRef.key,clean=safeFileName(file.name),path=`${activeUser.uid}/${id}/${clean}`,contentType=canonicalFileType(kind);showUploadToast(file.name,"Subiendo a Supabase...");try{await limitWait(uploadDocument(file,path,contentType),90000);showUploadToast(file.name,"Guardando en Archivos...");await limitWait(set(itemRef,{type:"file",name:clean,parentId:currentFolderId||null,fileType:kind,extension:fileExtension(clean),size:file.size,mimeType:contentType,storageProvider:"supabase",storagePath:path,createdAt:serverTimestamp(),updatedAt:serverTimestamp()}));showUploadToast(file.name,"Listo",true)}catch(error){console.error(error);try{await storageApi("delete",{path})}catch(cleanupError){console.error(cleanupError)}showUploadToast(file.name,uploadErrorMessage(error),false,true)}}}finally{$("uploadFileButton").disabled=false;$("fileUploadInput").value=""}}
function showUploadToast(name,status,done=false,error=false){clearTimeout(showUploadToast.timer);$("filesUploadToast").classList.remove("hidden");$("filesUploadToast").classList.toggle("done",done);$("filesUploadToast").classList.toggle("error",error);$("filesUploadTitle").textContent=done?"Archivo subido":error?"No se pudo subir":name;$("filesUploadStatus").textContent=status;if(done||error)showUploadToast.timer=setTimeout(hideUploadToast,error?5000:1800)}
function hideUploadToast(){clearTimeout(showUploadToast.timer);$("filesUploadToast").classList.add("hidden");$("filesUploadToast").classList.remove("done","error")}
async function getDriveFileUrl(item,download=false){if(item.storageProvider!=="supabase")throw new Error("Este archivo pertenece al almacenamiento anterior.");const data=await storageApi("signed-url",{path:item.storagePath,download:download?item.name:false});return data.url}
async function openDriveFile(item,download=false){const popup=download?null:window.open("about:blank","_blank");try{const url=await getDriveFileUrl(item,download);if(download){const a=document.createElement("a");a.href=url;a.rel="noopener";a.download=item.name;document.body.appendChild(a);a.click();a.remove()}else if(popup){popup.opener=null;popup.location=url}else window.open(url,"_blank","noopener")}catch(error){if(popup)popup.close();console.error(error);window.alert("No se pudo abrir el archivo.")}}
async function deleteDriveFile(item){if(item.storagePath&&item.storageProvider==="supabase")await storageApi("delete",{path:item.storagePath});await remove(ref(database,drivePath(item.id)))}
async function deleteDriveItem(item){if(item.type==="file"){if(!window.confirm(`¿Eliminar “${item.name}”?`))return;await deleteDriveFile(item);return}const descendants=descendantFolderIds(item.id),allFolderIds=new Set([item.id,...descendants]),files=driveItems.filter(child=>child.type==="file"&&allFolderIds.has(normalizeParentId(child.parentId))),folders=driveItems.filter(child=>child.type==="folder"&&allFolderIds.has(child.id));if(!window.confirm(`¿Eliminar la carpeta “${item.name}”${files.length||folders.length>1?" y todo su contenido":""}?`))return;for(const file of files)await deleteDriveFile(file);await Promise.all(folders.map(folder=>remove(ref(database,drivePath(folder.id)))))}
$("newFolderButton").addEventListener("click",openNewFolderModal);$("uploadFileButton").addEventListener("click",()=>$("fileUploadInput").click());$("fileUploadInput").addEventListener("change",event=>uploadFiles(event.target.files));
$("folderForm").addEventListener("submit",async event=>{event.preventDefault();const name=$("folderName").value.trim();if(!name){$("folderError").textContent="Escribí un nombre para la carpeta.";$("folderError").classList.remove("hidden");return}const duplicate=childItems().some(item=>item.type==="folder"&&item.name.toLowerCase()===name.toLowerCase());if(duplicate){$("folderError").textContent="Ya existe una carpeta con ese nombre acá.";$("folderError").classList.remove("hidden");return}$("saveFolderButton").disabled=true;try{await createFolder(name);closeFilesModal("folderModal")}catch(error){console.error(error);$("folderError").textContent="No se pudo crear la carpeta.";$("folderError").classList.remove("hidden")}finally{$("saveFolderButton").disabled=false}})
$("editItemForm").addEventListener("submit",async event=>{event.preventDefault();const item=getDriveItem(editingDriveItemId);if(!item)return;const base=$("editItemName").value.trim(),parentId=normalizeParentId($("editItemParent").value);if(!base){$("editItemError").textContent="El nombre no puede quedar vacío.";$("editItemError").classList.remove("hidden");return}const finalName=item.type==="file"?`${safeFileName(fileBaseName(base))}.${item.extension||fileExtension(item.name)}`:safeFileName(base);const duplicate=driveItems.some(other=>other.id!==item.id&&normalizeParentId(other.parentId)===parentId&&other.type===item.type&&String(other.name).toLowerCase()===finalName.toLowerCase());if(duplicate){$("editItemError").textContent="Ya existe un elemento con ese nombre en esa ubicación.";$("editItemError").classList.remove("hidden");return}$("saveEditItemButton").disabled=true;try{await update(ref(database,drivePath(item.id)),{name:finalName,parentId:parentId||null,updatedAt:serverTimestamp()});closeFilesModal("editItemModal")}catch(error){console.error(error);$("editItemError").textContent="No se pudieron guardar los cambios.";$("editItemError").classList.remove("hidden")}finally{$("saveEditItemButton").disabled=false}})
document.querySelectorAll("[data-close-files-modal]").forEach(button=>button.addEventListener("click",()=>closeFilesModal(button.dataset.closeFilesModal)));
$("filesBreadcrumbs").addEventListener("click",event=>{const button=event.target.closest("button[data-folder-id]");if(!button)return;currentFolderId=button.dataset.folderId==="root"?null:button.dataset.folderId;$("filesSearch").value="";renderDriveItems()});
$("filesGrid").addEventListener("click",async event=>{const button=event.target.closest("[data-drive-action]");if(!button)return;const item=getDriveItem(button.dataset.id);if(!item)return;const action=button.dataset.driveAction;if(action==="open-folder"){currentFolderId=item.id;$("filesSearch").value="";renderDriveItems()}else if(action==="open-file")await openDriveFile(item);else if(action==="edit-content")await openFileContentEditor(item);else if(action==="download")await openDriveFile(item,true);else if(action==="edit")openEditDriveItem(item);else if(action==="delete")await deleteDriveItem(item)});
$("filesSearch").addEventListener("input",renderDriveItems);$("filesGridToggle").addEventListener("click",()=>{filesViewMode="grid";$("filesGridToggle").classList.add("active");$("filesListToggle").classList.remove("active");renderDriveItems()});$("filesListToggle").addEventListener("click",()=>{filesViewMode="list";$("filesListToggle").classList.add("active");$("filesGridToggle").classList.remove("active");renderDriveItems()});
$("filesEmpty").addEventListener("click",event=>{const action=event.target.closest("[data-files-action]")?.dataset.filesAction;if(action==="new-folder")openNewFolderModal();else if(action==="upload")$("fileUploadInput").click()});
const dropZone=$("filesDropZone");["dragenter","dragover"].forEach(type=>dropZone.addEventListener(type,event=>{event.preventDefault();dropZone.classList.add("dragging")}));["dragleave","drop"].forEach(type=>dropZone.addEventListener(type,event=>{event.preventDefault();dropZone.classList.remove("dragging")}));dropZone.addEventListener("drop",event=>uploadFiles(event.dataTransfer.files));

/* Tooltips accesibles para los controles con iconos de Archivos */
const filesTooltip=document.createElement("div");filesTooltip.className="files-tooltip";filesTooltip.setAttribute("role","tooltip");document.body.appendChild(filesTooltip);let tooltipTarget=null;
function isFilesIconControl(button){return button&&!button.classList.contains("files-modal-backdrop")&&Boolean(button.closest(".files-view,.files-modal-card,.file-editor-card"))&&Boolean(button.getAttribute("aria-label")||button.dataset.tooltip)}
function showFilesTooltip(button){if(!isFilesIconControl(button))return;tooltipTarget=button;filesTooltip.textContent=button.dataset.tooltip||button.getAttribute("aria-label");filesTooltip.classList.add("visible");const rect=button.getBoundingClientRect(),half=filesTooltip.offsetWidth/2,left=Math.min(window.innerWidth-half-10,Math.max(half+10,rect.left+rect.width/2));filesTooltip.style.left=`${left}px`;filesTooltip.style.top=`${Math.max(10,rect.top-9)}px`}
function hideFilesTooltip(){tooltipTarget=null;filesTooltip.classList.remove("visible")}
document.addEventListener("pointerover",event=>{const button=event.target.closest("button");if(button!==tooltipTarget)showFilesTooltip(button)});document.addEventListener("pointerout",event=>{if(tooltipTarget&&!tooltipTarget.contains(event.relatedTarget))hideFilesTooltip()});document.addEventListener("focusin",event=>showFilesTooltip(event.target.closest("button")));document.addEventListener("focusout",hideFilesTooltip);window.addEventListener("scroll",hideFilesTooltip,true);window.addEventListener("resize",hideFilesTooltip);


/* Editor básico de contenido para Word (.docx) y PDF */
function setFileEditorLoading(loading){$("fileEditorLoading").classList.toggle("hidden",!loading);$("docxEditorWrap").classList.add("hidden");$("pdfEditorWrap").classList.add("hidden");$("saveFileContentButton").disabled=loading}
function closeFileContentEditor(){editingFileContentId=null;pdfPendingAnnotations=[];$("fileEditorModal").classList.add("hidden");$("docxEditor").innerHTML="";$("pdfPreviewFrame").src="about:blank";$("fileEditorError").classList.add("hidden");document.body.classList.remove("modal-open")}
async function fetchDriveBlob(item){const url=await getDriveFileUrl(item),response=await fetch(url);if(!response.ok)throw new Error("No se pudo descargar el archivo");return await response.blob()}
async function openFileContentEditor(item){if(item.type!=="file")return;if(item.fileType!=="pdf"&&item.extension!=="docx"){window.alert("La edición de contenido está disponible para PDF y Word .docx.");return}editingFileContentId=item.id;pdfPendingAnnotations=[];$("fileEditorTitle").textContent=item.name;$("fileEditorType").textContent=item.fileType==="pdf"?"PDF":"WORD";$("fileEditorSubtitle").textContent=item.fileType==="pdf"?"Agregá texto y guardá una nueva versión sobre el mismo archivo.":"Editá texto y formato básico directamente desde el Hub.";$("fileEditorError").classList.add("hidden");$("fileEditorModal").classList.remove("hidden");document.body.classList.add("modal-open");setFileEditorLoading(true);try{const blob=await fetchDriveBlob(item);if(item.fileType==="pdf"){const url=URL.createObjectURL(blob);$("pdfPreviewFrame").src=url;$("pdfPreviewFrame").dataset.objectUrl=url;const bytes=await blob.arrayBuffer(),pdfDoc=await PDFLib.PDFDocument.load(bytes);$("pdfAnnotationPage").max=String(pdfDoc.getPageCount());$("pdfAnnotationPage").value="1";$("pdfEditorWrap").classList.remove("hidden");renderPdfAnnotations()}else{if(!window.mammoth)throw new Error("No se cargó el editor de Word");const result=await window.mammoth.convertToHtml({arrayBuffer:await blob.arrayBuffer()});$("docxEditor").innerHTML=result.value||"<p></p>";$("docxEditorWrap").classList.remove("hidden")}}catch(error){console.error(error);$("fileEditorError").textContent="No se pudo cargar el editor de este archivo.";$("fileEditorError").classList.remove("hidden")}finally{$("fileEditorLoading").classList.add("hidden");$("saveFileContentButton").disabled=false}}
function renderPdfAnnotations(){$("pdfAnnotations").innerHTML=pdfPendingAnnotations.length?pdfPendingAnnotations.map((annotation,index)=>`<div class="pdf-annotation-chip"><span><b>Pág. ${annotation.page}</b>${escapeHTML(annotation.text)}</span><button type="button" data-remove-pdf-annotation="${index}" aria-label="Quitar"><i class="fa-solid fa-xmark"></i></button></div>`).join(""):'<p class="pdf-no-annotations">Todavía no agregaste texto.</p>'}
function wrapPdfText(text,font,size,maxWidth){const words=String(text).replace(/\s+/g," ").trim().split(" "),lines=[];let line="";for(const word of words){const test=line?`${line} ${word}`:word;if(font.widthOfTextAtSize(test,size)<=maxWidth)line=test;else{if(line)lines.push(line);line=word}}if(line)lines.push(line);return lines}
async function saveDocxContent(item){if(!window.htmlDocx)throw new Error("No se cargó el generador de Word");const html=`<!DOCTYPE html><html><head><meta charset="utf-8"><style>body{font-family:Arial,sans-serif;font-size:11pt;line-height:1.5}p{margin:0 0 8pt}ul,ol{margin:0 0 8pt 18pt}</style></head><body>${$("docxEditor").innerHTML}</body></html>`,blob=window.htmlDocx.asBlob(html);await uploadDocument(blob,item.storagePath,"application/vnd.openxmlformats-officedocument.wordprocessingml.document",true);await update(ref(database,drivePath(item.id)),{size:blob.size,downloadURL:null,updatedAt:serverTimestamp()})}
async function savePdfContent(item){if(!pdfPendingAnnotations.length)return;const original=await fetchDriveBlob(item),pdfDoc=await PDFLib.PDFDocument.load(await original.arrayBuffer()),font=await pdfDoc.embedFont(PDFLib.StandardFonts.Helvetica);for(const [index,annotation] of pdfPendingAnnotations.entries()){const page=pdfDoc.getPage(Math.min(Math.max(annotation.page-1,0),pdfDoc.getPageCount()-1)),{width,height}=page.getSize(),size=annotation.size,maxWidth=Math.max(120,width-90),lines=wrapPdfText(annotation.text,font,size,maxWidth),blockHeight=lines.length*(size+4);let y=annotation.position==="bottom"?45:annotation.position==="center"?(height-blockHeight)/2:height-55;for(const line of lines){page.drawText(line,{x:45,y,size,font,color:PDFLib.rgb(.12,.13,.12),maxWidth});y-=size+4}}const bytes=await pdfDoc.save(),blob=new Blob([bytes],{type:"application/pdf"});await uploadDocument(blob,item.storagePath,"application/pdf",true);await update(ref(database,drivePath(item.id)),{size:blob.size,downloadURL:null,updatedAt:serverTimestamp()})}
$("fileEditorDownload").addEventListener("click",()=>{const item=getDriveItem(editingFileContentId);if(item)openDriveFile(item,true)});document.querySelectorAll("[data-close-file-editor]").forEach(button=>button.addEventListener("click",closeFileContentEditor));document.querySelectorAll("[data-doc-command]").forEach(button=>button.addEventListener("click",()=>{document.execCommand(button.dataset.docCommand,false,null);$("docxEditor").focus()}));
$("pdfAddAnnotation").addEventListener("click",()=>{const text=$("pdfAnnotationText").value.trim(),page=Number($("pdfAnnotationPage").value),size=Number($("pdfAnnotationSize").value),maxPage=Number($("pdfAnnotationPage").max)||1;if(!text)return;if(!Number.isFinite(page)||page<1||page>maxPage){window.alert(`Elegí una página entre 1 y ${maxPage}.`);return}pdfPendingAnnotations.push({text,page,size:Math.min(32,Math.max(8,size||12)),position:$("pdfAnnotationPosition").value});$("pdfAnnotationText").value="";renderPdfAnnotations()});$("pdfAnnotations").addEventListener("click",event=>{const button=event.target.closest("[data-remove-pdf-annotation]");if(!button)return;pdfPendingAnnotations.splice(Number(button.dataset.removePdfAnnotation),1);renderPdfAnnotations()});
$("saveFileContentButton").addEventListener("click",async()=>{const item=getDriveItem(editingFileContentId);if(!item)return;$("saveFileContentButton").disabled=true;$("saveFileContentButton").textContent="Guardando...";$("fileEditorError").classList.add("hidden");try{if(item.fileType==="pdf")await savePdfContent(item);else await saveDocxContent(item);closeFileContentEditor();showUploadToast(item.name,"Cambios guardados",true)}catch(error){console.error(error);$("fileEditorError").textContent="No se pudieron guardar los cambios del documento.";$("fileEditorError").classList.remove("hidden")}finally{$("saveFileContentButton").disabled=false;$("saveFileContentButton").textContent="Guardar cambios"}})
